const data = $json;
const wfName = data.workflow?.name || 'Workflow desconocido';
const execId = data.execution?.id || 'N/A';
const execUrl = data.execution?.url || '';
const errMsg = data.execution?.error?.message || data.execution?.error?.description || 'Sin mensaje de error';
const nodeName = data.execution?.lastNodeExecuted || 'N/A';
const mode = data.execution?.mode || data.trigger?.mode || 'N/A';
const retryOf = data.execution?.retryOf || '';
const now = new Date().toLocaleString('es-DO', { timeZone: 'America/Santo_Domingo' });

const lines = [
  'FALLO EN AUTOMATIZACION',
  '',
  'Workflow: ' + wfName,
  'Nodo: ' + nodeName,
  'Modo: ' + mode,
  'Fecha: ' + now,
  'Ejecucion: #' + execId + (retryOf ? ' (reintento de #' + retryOf + ')' : ''),
  '',
  'Error: ' + errMsg,
];
if (execUrl) lines.push('', 'Ver detalle: ' + execUrl);

return [{ json: { text: lines.join('\n') } }];
